import {DEFAULT_VALUES} from '../../src/scoring.js';
export function installClickGame(d,{letters='KATTAIR'}={}){
 const rack=[...letters],pending=new Map(),committed=new Map(),clicks=[];let selected=null,blank=null,opponent=false;const root=d.querySelector('#board-parent');for(const cell of root.querySelectorAll('td')){const tile=cell.querySelector('.tile');if(tile){const l=[...tile.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent).join('').trim();committed.set(cell.id,{letter:l,blank:tile.classList.contains('blanktile')});}}
 const tile=(t,cls='')=>`<div class="tile ${cls}${t.blank?' blanktile':''}">${t.letter==='?'?' ':t.letter}<span class="letterscore">${t.blank||t.letter==='?'?0:DEFAULT_VALUES[t.letter]}</span></div>`;
 function render(){for(const cell of root.querySelectorAll('td')){const t=pending.get(cell.id)||committed.get(cell.id);cell.innerHTML=t?tile(t,pending.has(cell.id)?'racktile':''):'';cell.onclick=()=>{clicks.push(cell.id);if(opponent||selected===null||t)return;const token=rack[selected];if(!token)return;if(token==='?'){blank={index:selected,id:cell.id};render();return;}pending.set(cell.id,{letter:token,blank:false});rack[selected]='';selected=null;render();};}
 for(let i=0;i<7;i++){const cell=d.getElementById('sq_R'+(i+1));cell.innerHTML=rack[i]?tile({letter:rack[i],blank:rack[i]==='?'},'racktile'+(selected===i?' sel':'')):'';cell.onclick=()=>{clicks.push(cell.id);if(!opponent&&rack[i]){selected=selected===i?null:i;render();}};}
 d.getElementById('blank-dialog')?.remove();if(blank){const dialog=d.createElement('div');dialog.id='blank-dialog';dialog.innerHTML='<table id="blank-meaning"><tr>'+[...'AÁBDÐEÉFGHIÍJKLMNOÓPRSTUÚVXYÝÞÆÖ'].map(l=>`<td><div class="blank-choice">${l}</div></td>`).join('')+'</tr></table>';for(const e of dialog.querySelectorAll('td'))e.onclick=()=>{clicks.push('blank:'+e.textContent);pending.set(blank.id,{letter:e.textContent,blank:true});rack[blank.index]='';blank=null;selected=null;render();};d.body.append(dialog);}
 d.querySelector('.opp-turn')?.remove();if(opponent){const e=d.createElement('div');e.className='opp-turn';e.textContent='Opponent turn';d.body.append(e);}}
 const submit=d.createElement('button');submit.id='submit-test';submit.className='submitmove';submit.textContent='Submit';let submissions=0;submit.onclick=()=>submissions++;d.body.append(submit);render();
 return {rack,pending,committed,clicks,render,get submissions(){return submissions;},setOpponent(value){opponent=value;render();},commit(nextRack='STHRIÁ?'){for(const [id,t]of pending)committed.set(id,t);pending.clear();rack.splice(0,rack.length,...nextRack);selected=null;render();}};
}
